    function get_valid_address(a:integer) return integer is
    begin
        if    a >= 0   and a < 64  then
            return a;
        elsif a >= 64  and a < 128 then
            return a+8;
--        elsif a >= 128 and a < 198 then
--            return a+8+8;
--        elsif a >= 198 and a < 260 then
--            return a+8+8+2;
        elsif a >= 128 and a < 189 then
            return a+8+8;
        elsif a >= 189 and a < 259 then
            return a+8+8+11;
        else
            return 100000+a;
        end if;
    end function get_valid_address;
    function and_reduce(a : std_logic_vector; b:std_logic) return std_logic_vector is
        variable ret : std_logic_vector(31 downto 0) := (others => '0');
    begin
        for i in a'range loop
            ret(i) := a(i) and b;
        end loop;
        return ret;
    end function and_reduce;
