--    function onehotmux_or_reduce(a : std_logic_vector; b : std_logic_vector)  return std_logic_vector is
        variable ret : std_logic_vector(31 downto 0) := (others => '0');
        variable aux : std_logic_vector(31 downto 0) := (others => '0');
    begin
        for i in a'range loop
--            aux := b(i);
            aux := and_reduce(a(i),b(i));
            ret := ret or aux;
        end loop;
        return ret;
    end function onehotmux_or_reduce;
--    function or_reduce(a : output_type) return std_logic_vector is
    function or_reduce(a : parreg_type) return std_logic_vector is
        variable ret : std_logic_vector(31 downto 0) := (others => '0');
    begin
        for i in a'range loop
            ret := ret or a(i);
        end loop;
        return ret;
    end function or_reduce;
