    -- Reset to only obtain the output from one bank.
    process(bankID)
    begin
        rst1ID <= '1';
        rst2ID <= '1';
        rst3ID <= '1';
        rst4ID <= '1';
        case bankID is
            when "00" => rst1ID <= '0';
            when "01" => rst2ID <= '0';
            when "10" => rst3ID <= '0';
            when "11" => rst4ID <= '0';
            when others => rst1ID <= 'X';rst2ID <= 'X';rst3ID <= 'X';rst4ID <= 'X';
        end case;
    end process;
    process(bankEX)
    begin
        rst1EX <= '1';
        rst2EX <= '1';
        rst3EX <= '1';
        rst4EX <= '1';
        case bankEX is
            when "00" => rst1EX <= '0';
            when "01" => rst2EX <= '0';
            when "10" => rst3EX <= '0';
            when "11" => rst4EX <= '0';
            when others => rst1EX <= 'X';rst2EX <= 'X';rst3EX <= 'X';rst4EX <= 'X';
        end case;
    end process;
